package com.timelordmod.gallifrey.world;

import com.timelordmod.gallifrey.world.dimension.ModDimensions;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.entity.player.PlayerEntity;

/** Runtime Mars behaviour. Terrain itself is generated by Mars' noise settings. */
public final class MarsWorldHandler {
    private MarsWorldHandler() {}

    public static void register() {
        // Mars gravity is approximately 38% of Earth's. Vanilla applies roughly
        // -0.08 vertical acceleration, so restoring +0.05 gives a close gameplay
        // approximation without modifying gravity globally for every dimension.
        ServerTickEvents.END_WORLD_TICK.register(world -> {
            if (!world.getRegistryKey().equals(ModDimensions.MARS_LEVEL_KEY)) return;
            for (PlayerEntity player : world.getPlayers()) {
                if (!player.isOnGround() && !player.isClimbing() && !player.isSwimming() && !player.hasNoGravity()) {
                    // Vanilla gravity is about 0.08 blocks/tick^2. Add back 0.05
                    // each airborne tick, leaving roughly 0.03 (about 38% of Earth).
                    // Apply during ascent and descent so the whole jump arc is affected.
                    var velocity = player.getVelocity();
                    player.setVelocity(velocity.x, velocity.y + 0.05, velocity.z);
                    player.velocityDirty = true;
                }
            }
        });
    }
}
